"""Shared refresh controller: user intent is separate from reading suppression."""
from clearparcel.datawatch.csp import SCRIPT_TAG


def refresh_script(seconds: int, *, public: bool = False) -> str:
    if not seconds:
        return ""
    return SCRIPT_TAG + '\n' + _SCRIPT.replace('__DELAY__', str(int(seconds) * 1000)).replace('__PUBLIC__', 'true' if public else 'false') + '\n</script>'


_SCRIPT = r"""
(function(){
const delay=__DELAY__,isPublic=__PUBLIC__,key='watchtower-view:'+location.pathname+location.search;
const ids=['q','cat','health','cq','cs','mngac-metric','mngac-county-select','mngac-q','mngac-inclusion','cmq','cmi','overview-metric','overview-county-select','gap-standard','gac-field-search','gac-field-inclusion','activity-q','change-type','change-start','change-end','terms-q','terms-status','source-sort','check-timing','gac-county-search'];
let timer=null,userPaused=false,revision=null,etag=null,busy=false,lastSummary=null,initialized=false;
const holds=new Set();
function save(){if(!initialized)return;const values={userPaused,scroll:window.scrollY};ids.forEach(id=>{const el=document.getElementById(id);if(el)values[id]=el.value});values.details=[...document.querySelectorAll('details[id]')].filter(d=>d.open).map(d=>d.id);values.focusKey=document.activeElement?.dataset?.refreshKey||'';values.focus=document.activeElement?.id||'';values.focusCounty=document.activeElement?.dataset?.slug||'';try{if(document.activeElement?.closest?.('#reading-update')){const old=JSON.parse(sessionStorage.getItem(key)||'{}');values.focus=old.focus;values.focusKey=old.focusKey}sessionStorage.setItem(key,JSON.stringify(values))}catch(e){}}
function restore(){try{const values=JSON.parse(sessionStorage.getItem(key)||'{}');userPaused=values.userPaused===true;ids.forEach(id=>{const el=document.getElementById(id);if(el&&values[id]!==undefined){el.value=values[id];el.dispatchEvent(new Event(el.tagName==='SELECT'?'change':'input',{bubbles:true}))}});if(Array.isArray(values.details))values.details.forEach(id=>{const d=document.getElementById(id);if(d?.tagName==='DETAILS')d.open=true});if(values.focus)document.getElementById(values.focus)?.focus({preventScroll:true});else if(values.focusKey)[...document.querySelectorAll('[data-refresh-key]')].find(e=>e.dataset.refreshKey===values.focusKey)?.focus({preventScroll:true});else if(values.focusCounty)[...document.querySelectorAll('.mngac-county')].find(p=>p.dataset.slug===values.focusCounty)?.focus({preventScroll:true});if(Number.isFinite(values.scroll))window.scrollTo(0,values.scroll)}catch(e){}}
function reading(){return holds.size>0||document.getElementById('county-profile-dialog')?.open||!!document.querySelector('.profile-evidence[open]')||!!document.querySelector('.public-export[open]')||!!document.querySelector('details[open]')||!!document.activeElement?.matches?.('input,select,textarea')}
function label(){const button=document.getElementById('refresh-pause');if(button){button.textContent=userPaused?'Resume refresh':'Pause refresh'}}
function schedule(){clearTimeout(timer);timer=null;if(!initialized)return;label();if(!userPaused&&!document.hidden&&!holds.size)timer=setTimeout(tick,delay)}
const SKEW_MS=300000;
function ahead(stamp){return Number.isFinite(stamp)&&stamp-Date.now()>SKEW_MS}
function relative(value){const stamp=Date.parse(value);if(!Number.isFinite(stamp)||ahead(stamp))return 'Unavailable';const seconds=Math.max(0,Math.floor((Date.now()-stamp)/1000));if(seconds<60)return 'Just now';const minutes=Math.floor(seconds/60);if(minutes<60)return minutes+' min ago';const hours=Math.floor(minutes/60);return hours<48?hours+' hr ago':Math.floor(hours/24)+' days ago'}
function publication(summary){const badge=document.querySelector('[data-age-kind="publication"]');if(badge)badge.dataset.ageTime=summary.public_published_at||'';const publicationTime=document.getElementById('public-publication-time');if(publicationTime)publicationTime.textContent=summary.public_published_at?new Date(summary.public_published_at).toLocaleString('en-US',{timeZone:'America/Chicago',timeZoneName:'short'}):'Unavailable';document.querySelectorAll('[data-age-time]').forEach(node=>node.textContent=relative(node.dataset.ageTime));document.querySelectorAll('[data-worker-report]').forEach(node=>{const worker=summary.workers?.[node.dataset.workerReport];if(!worker)return;const stamp=Date.parse(worker.last_report_at||worker.checked_at);const limit=(summary.thresholds?.worker_stale_minutes||1560)*60000;const reporting=!Number.isFinite(stamp)||ahead(stamp)?'Report time unavailable':Date.now()-stamp>limit?'Reporting overdue':'Reporting on time';const health={ok:'Checks passing',warn:'Some checks need attention',error:'Checks failed'}[worker.overall]||'Unknown';node.textContent=health+' · '+reporting});const target=document.getElementById('public-publication-status');if(target){const time=summary.public_published_at;const parsed=Date.parse(time);const age=Number.isFinite(parsed)&&!ahead(parsed)?Math.max(0,Math.floor((Date.now()-parsed)/1000)):null;const limit=summary.thresholds?.publication_max_age_seconds||1800;target.textContent='Dashboard update status: '+(age===null?'Unknown':age>limit?'Overdue':'Current')+' · '+(time?new Date(time).toLocaleString('en-US',{timeZone:'America/Chicago',timeZoneName:'short'}):'Unavailable');target.title=time||''}const sourceTarget=document.getElementById('source-reporting-status');if(sourceTarget){const limit=(summary.thresholds?.source_stale_minutes||1560)*60*1000;let overdue=0,missing=0;Object.values(summary.source_observations||{}).forEach(source=>{const t=Date.parse(source.checked_at);if(!Number.isFinite(t)||ahead(t))missing++;else if(Date.now()-t>limit)overdue++});sourceTarget.textContent='Source checks: '+overdue+' overdue · '+missing+' without a check time. Source check time is separate from the dashboard update time.'}}
function offerUpdate(){if(!document.createElement||document.getElementById('reading-update'))return;const target=document.getElementById('refresh-status');if(!target)return;const notice=document.createElement('div');notice.id='reading-update';notice.className='reading-update';notice.append('Automatic update held while you read. ');const button=document.createElement('button');button.type='button';button.textContent='Update view';button.addEventListener('click',()=>{save();location.reload()});notice.append(button);target.append(notice)}
async function tick(){timer=null;if(userPaused||document.hidden||busy){schedule();return}busy=true;try{
 if(!isPublic){if(reading())offerUpdate();else{save();location.reload()}return}
 const controller=new AbortController(),deadline=setTimeout(()=>controller.abort(),10000);
 let response;try{response=await fetch('/api/summary',{headers:etag?{'If-None-Match':etag}:{},cache:'no-cache',signal:controller.signal})}finally{clearTimeout(deadline)}
 if(response.status===304){if(lastSummary){publication(lastSummary);if(lastSummary.content_revision!==revision){if(reading())offerUpdate();else if(!userPaused&&!document.hidden){save();location.reload()}}}return;}if(!response.ok)throw new Error('summary unavailable');
 const summary=await response.json();if(summary.schema_version!==1||typeof summary.content_revision!=='string')throw new Error('invalid summary');
 etag=response.headers.get('ETag');lastSummary=summary;publication(summary);if(revision!==null&&summary.content_revision!==revision&&reading())offerUpdate();
 if(revision===null){revision=summary.content_revision;window.watchtowerContentRevision=revision}
 else if(summary.content_revision!==revision&&!userPaused&&!document.hidden&&!reading()){save();location.reload()}
 const status=document.getElementById('refresh-status');if(status&&!document.getElementById('reading-update'))status.textContent=summary.refresh_failed?'Storage refresh unavailable; showing cached observations.':'';
 }catch(e){const status=document.getElementById('refresh-status');if(status)status.textContent='Refresh unavailable; showing the last loaded observations.';etag=null}
 finally{busy=false;schedule()}}
function pause(){userPaused=true;save();schedule()}
function resume(){userPaused=false;save();schedule()}
function suspend(reason='dialog'){holds.add(reason);schedule()}
function release(reason='dialog'){holds.delete(reason);schedule()}
window.watchtowerRefresh={pause,resume,suspend,release,save,paused:()=>userPaused};
document.addEventListener('DOMContentLoaded',()=>{initialized=false;document.querySelectorAll('details').forEach((d,i)=>{if(!d.id)d.id='reading-section-'+i});document.querySelectorAll('a[href],button,input,select,textarea,summary').forEach((e,i)=>{if(e.dataset){const scope=e.closest?.('.mobile-nav')?'mobile:':e.closest?.('.sidebar')?'sidebar:':'';e.dataset.refreshKey=scope+(e.id||e.dataset.slug||(e.tagName==='SUMMARY'?e.closest?.('details')?.id:'')||e.getAttribute?.('href')||e.getAttribute?.('name')||e.textContent?.trim().slice(0,80)||String(i))}});revision=document.querySelector('[data-content-revision]')?.dataset.contentRevision||null;window.watchtowerContentRevision=revision;restore();initialized=true;document.getElementById('refresh-pause')?.addEventListener('click',()=>userPaused?resume():pause());ids.forEach(id=>{const el=document.getElementById(id);el?.addEventListener(el.tagName==='SELECT'?'change':'input',save)});schedule()});
document.addEventListener('toggle',save,true);document.addEventListener('visibilitychange',schedule);window.addEventListener('pagehide',save);
})();
"""
